  "bhagirathibai": { "av": "🌸", "en": "Bhāgīrathībāī", "te": "భాగీరథీబాయి", "d": "Wife of Moropant Tāmbe and mother of Lakṣmībāī; she died when her daughter was about four years old.", "dt": "మోరోపంత్ తాంబే భార్య, లక్ష్మీబాయి తల్లి; కూతురికి సుమారు నాలుగేళ్ళప్పుడే చనిపోయింది." },
  "bajirao2": { "av": "🏚️", "en": "Peśvā Bājī Rāo II", "te": "రెండవ బాజీరావ్ పేష్వా", "d": "The last Peśvā of the Marathas (in office 1796–1818). Defeated by the East India Company in 1818, he gave up his lands for a yearly pension and lived at Bithūr on the Gaṅgā near Kanpur until his death in 1851. (Not Bājī Rāo I.)", "dt": "మరాఠాల చివరి పేష్వా (1796–1818). 1818లో ఈస్ట్ ఇండియా కంపెనీ చేతిలో ఓడిపోయి, ఏటా పింఛను తీసుకుని రాజ్యాన్ని వదులుకున్నాడు; కాన్పూర్ దగ్గర గంగ ఒడ్డున బిఠూర్‌లో 1851లో చనిపోయే వరకు ఉన్నాడు. (మొదటి బాజీరావ్ కాదు.)" },
  "nanasahib": { "av": "🏯", "en": "Nānā Sāhib", "te": "నానా సాహెబ్", "d": "Dhoṇḍū Pant, adopted son of Peśvā Bājī Rāo II, brought up at Bithūr. The Company refused to continue the Peśvā's pension to him; in 1857 he led the rising at Kanpur. He disappeared into Nepal in 1859 and his end is not known.", "dt": "రెండవ బాజీరావ్ పేష్వా దత్తపుత్రుడు ధోండూ పంత్; బిఠూర్‌లో పెరిగాడు. పేష్వా పింఛనును కంపెనీ ఆయనకు కొనసాగించలేదు; 1857లో కాన్పూర్ తిరుగుబాటుకు నాయకత్వం వహించాడు. 1859లో నేపాల్ అడవుల్లోకి వెళ్ళిపోయాడు; ఆయన అంతం ఏమైందో తెలియదు." },
  "raosahib": { "av": "🎌", "en": "Rāo Sāhib", "te": "రావ్ సాహెబ్", "d": "Pāṇḍuraṅg Rāo, a kinsman of Nānā Sāhib (usually called his nephew), brought up at Bithūr; a leader of the 1857–58 rising in Central India with Tātyā Ṭope and the Rāṇī. He was captured in 1862 and executed.", "dt": "నానా సాహెబ్ బంధువు (సాధారణంగా ఆయనకు అన్న కొడుకు వరస అని చెబుతారు) పాండురంగ రావ్; బిఠూర్‌లో పెరిగాడు. తాత్యా తోపే, రాణిలతో కలిసి 1857–58లో మధ్య భారత తిరుగుబాటుకు నాయకుల్లో ఒకడు. 1862లో పట్టుబడి ఉరిశిక్షకు గురయ్యాడు." },
  "tatyatope": { "av": "🏹", "en": "Tātyā Ṭope", "te": "తాత్యా తోపే", "d": "Rāmcandra Pāṇḍuraṅg, a Marathi Brahmin of Nānā Sāhib's household at Bithūr, who became the most able general of the 1857–58 rising in Central India. Betrayed and captured in April 1859, he was hanged at Śivpurī on 18 April 1859.", "dt": "బిఠూర్‌లో నానా సాహెబ్ ఇంటి మనిషైన మరాఠీ బ్రాహ్మణుడు రామచంద్ర పాండురంగ్; 1857–58 మధ్య భారత తిరుగుబాటులో అందరికంటే నేర్పరి అయిన సేనాని. 1859 ఏప్రిల్‌లో నమ్మకద్రోహంతో పట్టుబడి, 1859 ఏప్రిల్ 18న శివపురిలో ఉరితీయబడ్డాడు." },
